    {"상황": "기도 응답이 없다고 느끼는 성도", "성경원리": "하나님은 '그리하면 주시리라'고 약속하셨다. 응답이 없는 것이 아니라 우리가 기대하는 형태가 아닐 수 있다. 또한 6절의 조건인 '믿음으로 구하라'를 점검해야 한다", "실제적용": "기도의 동기와 방법을 함께 점검하고 하나님의 응답이 다양한 형태로 올 수 있음을 나누라. 꾸짖지 않으시는 하나님의 성품을 신뢰하도록 격려하라"}
