    {"항목": "유대 지혜문학의 의심 경고", "내용": "구약 지혜문학에서 두 마음(8절)을 품는 것은 하나님과 우상 사이에서 방황하는 것을 의미했다(왕상 18:21). 야고보는 이 전통을 기도의 맥락에 적용한다", "목회적활용": "의심은 단순한 감정적 동요가 아니라 하나님에 대한 충성의 문제이다"}
