    {"구분": "욥의 상실과 회복", "내용": "욥은 동방에서 가장 부유한 자였으나 하루아침에 모든 것을 잃었다(욥 1장). 그러나 고난 후에 하나님을 더 깊이 알게 되었으며 이전보다 더 큰 복을 받았다", "그리스도연결": "그리스도 안에서 잃어버린 모든 것이 회복된다. 세상의 부를 잃어도 그리스도를 얻으면 영원한 부를 얻는다(빌 3:8)"}
