    {"새찬송가": "449", "통일찬송가": "366", "제목": "내 갈 길 멀고 밤은 깊은데", "선정이유": "세상의 덧없음 속에서 영원한 소망을 바라보는 찬양이다"},
    {"새찬송가": "488", "통일찬송가": "352", "제목": "내 주 되신 주를 참 사랑하고", "선정이유": "물질이 아닌 주님을 사랑함의 고백을 담는다"}
