    {"새찬송가": "345", "통일찬송가": "464", "제목": "주의 진리 위해 십자가 군기", "선정이유": "신앙의 전투에서 승리하여 면류관을 얻는 결의를 담는다"},
    {"새찬송가": "254", "통일찬송가": "172", "제목": "면류관 벗어서", "선정이유": "면류관의 영광을 직접 다루는 찬양이다"}
