    {"대지": "서론", "내용": "야고보는 이 짧은 문장으로 앞의 교훈을 마무리하고 새로운 교훈을 시작한다. '속지 말라'는 하나님의 성품에 대한 거짓된 이해를 경고하는 전환점이다", "예화_적용": "도로의 경고 표지판은 운전자를 귀찮게 하려는 것이 아니라 보호하려는 것이다. 야고보의 경고도 사랑에서 나온 것이다"},
    {"대지": "1대지: 사랑하는 형제들 (관계)", "내용": "경고는 관계 안에서 주어질 때 효과적이다. 야고보는 먼저 '사랑하는'이라는 관계를 확인한 후 경고한다", "예화_적용": "의사의 경고를 듣는 것은 의사를 신뢰하기 때문이다. 사랑의 관계가 경고의 기반이다"},
    {"대지": "2대지: 속지 말라 (경고)", "내용": "속임의 가장 큰 위험은 속았다는 사실 자체를 모르는 것이다. 말씀의 거울 앞에 서야 자기 속임을 발견할 수 있다", "예화_적용": "거울이 없으면 얼굴의 얼룩을 알 수 없다. 하나님의 말씀이 영적 거울이 되어 속임을 드러내 준다"},
    {"대지": "3대지: 진리로의 전환 (방향)", "내용": "16절은 13-15절의 속임(유혹의 원인을 하나님께 돌림)에서 17절의 진리(모든 선한 것은 하나님에게서 옴)로 전환하는 다리이다", "예화_적용": "속임에서 벗어나는 길은 진리를 아는 것이다(요 8:32). 진리가 우리를 자유케 한다"},
    {"대지": "결론", "내용": "속지 않으려면 하나님의 성품을 바르게 알아야 한다. 17절에서 밝혀지듯 하나님은 선한 은사만 주시는 분이시다. 이 진리 위에 서면 속임에서 자유해진다", "예화_적용": "가짜 화폐를 식별하는 최선의 방법은 진짜 화폐를 많이 만져보는 것이다. 하나님의 진리를 많이 알수록 거짓에 속지 않게 된다"}
