    {"상황": "거짓 교훈에 현혹되어 혼란스러운 성도", "성경원리": "하나님에 대한 바른 이해가 모든 진리의 기초이다. 하나님의 성품을 왜곡하는 가르침은 아무리 매력적이어도 거짓이다", "실제적용": "성경 전체의 맥락에서 가르침을 검증하도록 안내하라. 한 구절만 따로 떼어 가르치는 것을 주의하고 성경 전체의 증언으로 분별하라"}
