    {"대지": "2대지: 듣기만 하는 자 (경고)", "내용": "아크로아테스(듣는 자)는 청강생처럼 듣기만 하는 사람이다. 많은 설교를 들어도 행하지 않으면 영적 성장이 없다", "예화_적용": "헬스장 회원권을 가지고 있어도 운동하지 않으면 근육이 자라지 않는다. 말씀을 들어도 행하지 않으면 영적 근육이 자라지 않는다"},
    {"대지": "3대지: 자신을 속이는 자 (위험)", "내용": "듣기만 하는 자의 가장 큰 위험은 자기 기만이다. 들었으니 알고 있다, 알고 있으니 충분하다고 스스로를 속인다", "예화_적용": "수영 이론을 완벽히 아는 사람이 물에 빠지면 이론이 소용없다. 행함 없는 지식은 위기의 순간에 무력하다"},
    {"대지": "결론", "내용": "오늘 들은 말씀을 한 가지만이라도 실천하자. 작은 순종이 큰 변화의 시작이다. 듣는 자에서 행하는 자로의 전환이 참된 신앙의 증거이다", "예화_적용": "허드슨 테일러는 '중국을 위해 천 명의 선교사를 기도했으나 그 첫 번째 선교사는 나 자신이었다'고 했다. 행함은 자기 자신부터 시작한다"}
