    {"구분": "기드온의 선택", "내용": "하나님은 32,000명 중 300명만을 선택하셨다(삿 7장). 수의 많고 적음, 힘의 강하고 약함이 아닌 하나님의 기준으로 선택하셨다", "그리스도연결": "그리스도는 열두 제자를 부르실 때 어부, 세리 등 세상이 무시하는 자들을 택하셨다. 하나님의 선택 기준은 세상과 다르다"}
