    {"구절": "고전 12:13", "연결점": "유대인이나 헬라인이나 종이나 자유인이나 다 한 성령으로 세례를 받아 한 몸이 되었고", "구분": "신약"},
    {"구절": "레 19:15", "연결점": "가난한 자의 편을 들지 말며 세력 있는 자의 낯을 두려워하지 말고 공의로 사람을 재판할지니라", "구분": "구약"},
    {"구절": "신 1:17", "연결점": "재판할 때에 외모를 보지 말고 귀천을 일반으로 듣고", "구분": "구약"},
    {"구절": "눅 14:12-13", "연결점": "잔치를 베풀거든 차라리 가난한 자들, 병신들, 저는 자들, 소경들을 청하라", "구분": "신약"},
    {"구절": "마 22:16", "연결점": "당신은 참되시고 참으로 하나님의 도를 가르치시며 아무도 꺼리는 일이 없으시니 이는 사람의 외모를 보지 아니하심이니이다", "구분": "신약"},
    {"구절": "잠 22:2", "연결점": "부자와 가난한 자가 함께 살거니와 다 여호와의 지으신 바니라", "구분": "구약"},
    {"구절": "욥 34:19", "연결점": "왕족을 외모로 보지 아니하시며 부자를 가난한 자보다 더 생각지 아니하시나니 이는 그들이 다 그 손의 지으신 바가 됨이니라", "구분": "구약"}
