    {"항목": "로마 법정의 편파", "내용": "로마 법정에서는 시민권과 재산에 따라 대우가 달랐다. 부유한 자는 유리한 판결을 받기 쉬웠고 가난한 자는 불리한 위치에 놓였다. 이 불공정한 체계를 부자들이 이용하고 있었다", "목회적활용": "정의를 추구하는 것은 교회의 본질적 사명이다. 약한 자의 편에 서는 것이 하나님의 뜻이다"}
