  "표6_설교자료": [
    {"대지": "제목", "내용": "믿음이 있노라 하고 — 말과 삶의 간격", "예화_적용": "고백하는 믿음과 살아내는 믿음의 차이를 깨닫고 참된 믿음으로 나아가게 하는 설교"},
    {"대지": "서론", "내용": "교회에서 가장 흔한 말 중 하나가 '나는 믿습니다'입니다. 그러나 야고보는 도발적으로 묻습니다. '그 믿음이 능히 자기를 구원하겠느냐?' 이 질문 앞에 우리 모두는 겸허해져야 합니다.", "예화_적용": "자격증이 있다고 해서 실력이 있는 것은 아닙니다. 운전면허가 있어도 운전을 전혀 하지 않는 사람이 있습니다. 믿음의 면허증만으로는 부족합니다."},
    {"대지": "1대지: 말만의 믿음 (공허한 고백)", "내용": "야고보가 문제 삼는 것은 '믿음이 있노라 하고(레게)' 즉 말만 하는 것이다. 입으로는 고백하지만 삶에서 증거가 없는 믿음이다.", "예화_적용": "사랑한다고 말하면서 행동으로는 전혀 보여주지 않는 사람을 우리는 신뢰하지 않습니다. 하나님도 말뿐인 고백을 기뻐하지 않으십니다."},
    {"대지": "2대지: 행함의 결여 (열매 없는 나무)", "내용": "행함이 없다는 것은 율법적 공로를 못 쌓았다는 뜻이 아니라, 믿음의 자연스러운 열매가 없다는 것이다. 사과나무가 사과를 맺듯이 참된 믿음은 반드시 행함을 맺는다.", "예화_적용": "봄에 아무리 예쁜 꽃이 피어도 가을에 열매가 없으면 그 나무는 문제가 있는 것입니다(마 21:19). 믿음도 마찬가지입니다."},
    {"대지": "3대지: 구원의 질문 (생사의 문제)", "내용": "야고보의 질문은 수사적이다. 답은 '아니오'다. 행함이 없는 믿음은 구원의 능력이 없다. 이것은 행위 구원이 아니라, 참된 구원적 믿음의 본질에 대한 선언이다.", "예화_적용": "의사가 처방전을 써주었는데 약을 먹지 않으면 병이 낫지 않습니다. 믿음은 처방전이고, 행함은 약을 먹는 것입니다. 둘 다 필요합니다."},
    {"대지": "결론", "내용": "오늘 야고보의 질문이 우리에게 향합니다. '당신의 믿음에 행함이 있습니까?' 이것은 정죄가 아니라 점검입니다. 참된 믿음은 반드시 삶을 변화시킵니다. 우리의 고백이 삶으로 증명되는 한 주가 되기를 기도합니다.", "예화_적용": "이번 주에 당신의 믿음을 보여줄 한 가지 구체적 행동을 정하고 실천하십시오."}
  ],
