    {"구절": "계 3:17", "연결점": "네가 말하기를 나는 부자라 부요하여 부족한 것이 없다 하나 네가 곤고한 것과 가련한 것과 가난한 것과 눈 먼 것과 벌거벗은 것을 알지 못하도다", "구분": "신약"},
    {"구절": "히 6:7-8", "연결점": "땅이 그 위에 자주 내리는 비를 흡수하여 밭 가는 자들의 쓸 만한 채소를 내면 하나님께 복을 받고 만일 가시와 엉겅퀴를 내면 버림을 당하고", "구분": "신약"}
