    {"구절": "창 15:6", "연결점": "아브람이 여호와를 믿으니 여호와께서 이를 의로 여기시고 - 바울이 강조한 칭의의 시점", "구분": "구약"},
    {"구절": "히 11:17-19", "연결점": "아브라함은 시험을 받을 때에 믿음으로 이삭을 드렸으니... 저가 하나님이 능히 죽은 자 가운데서 다시 살리실 줄로 생각한지라", "구분": "신약"},
    {"구절": "롬 4:1-5", "연결점": "바울의 아브라함 칭의 해석 - 야고보와 보완적 관계", "구분": "신약"},
    {"구절": "요 3:16", "연결점": "하나님이 세상을 이처럼 사랑하사 독생자를 주셨으니 - 아브라함의 이삭 봉헌의 궁극적 성취", "구분": "신약"}
