    {"교리": "'믿음으로만 아니니라'의 정확한 의미", "설명": "야고보가 부정하는 것은 '솔라 피데' 원리가 아니라, 행함이 없는 죽은 믿음만으로 구원받을 수 있다는 왜곡된 주장이다. 참된 '오직 믿음'은 행함을 낳는 살아있는 믿음이다", "관련구절": "약 2:17, 약 2:26, 갈 5:6, 딛 2:14"}
