    {"대지": "3대지: 같은 진리의 양면 — 통합", "내용": "바울도 행함을 부정하지 않았고(엡 2:10), 야고보도 믿음을 부정하지 않았다(약 2:23). 둘의 가르침을 통합하면: 은혜로 구원받되, 그 믿음은 반드시 행함으로 드러난다.", "예화_적용": "전기(믿음)가 있어야 불이 켜지지만, 전구(행함)가 있어야 빛이 세상에 드러납니다."},
    {"대지": "결론", "내용": "은혜로 구원받되 행함으로 살아가는 것, 이것이 완전한 복음입니다. 바울과 야고보가 함께 부르는 화음에 우리의 삶을 맞추어 갑시다.", "예화_적용": "'나는 은혜로 구원받았습니다'라고 고백한 후, '그 은혜에 합당하게 살겠습니다'라고 결단하십시오."}
