    {"대지": "서론", "내용": "말(馬)은 강하고 빠른 동물입니다. 그러나 입에 물린 작은 재갈 하나로 완전히 제어됩니다. 야고보는 이 비유로 혀의 놀라운 힘을 설명합니다.", "예화_적용": "자동차의 핸들은 차 전체에 비하면 매우 작지만, 차의 방향을 완전히 결정합니다."},
    {"대지": "1대지: 작은 재갈 (혀의 크기)", "내용": "재갈은 말 전체에 비하면 극히 작다. 혀도 몸 전체에 비하면 작은 지체다. 그러나 크기가 영향력을 결정하지 않는다.", "예화_적용": "선박의 키도 배에 비하면 작지만 배의 방향을 결정합니다(4절)."},
    {"대지": "2대지: 큰 통제력 (혀의 힘)", "내용": "재갈 하나로 말 전체의 방향이 바뀌듯, 말 한 마디로 인생 전체의 방향이 바뀔 수 있다. 건설적으로도, 파괴적으로도.", "예화_적용": "한 마디 격려의 말이 사람을 살리기도 하고, 한 마디 비난의 말이 사람을 무너뜨리기도 합니다."},
    {"대지": "3대지: 순종의 방향 (혀의 사용)", "내용": "야고보는 재갈이 말을 '순종케' 한다고 말한다. 혀도 하나님께 순종하는 방향으로 사용되어야 한다. 혀의 방향이 삶의 방향을 결정한다.", "예화_적용": "매일 아침 '오늘 제 입술의 말이 하나님을 기쁘시게 하는 말이 되게 하소서'라고 기도해 보십시오."},
    {"대지": "결론", "내용": "작은 재갈이 큰 말을 어거하듯, 우리의 작은 혀가 삶 전체를 결정합니다. 혀의 재갈을 성령의 손에 맡기십시오.", "예화_적용": "오늘부터 '말의 재갈' 훈련을 시작하십시오. 화가 날 때 10초만 침묵해 보십시오."}
