    {"대지": "서론", "내용": "야고보의 진단은 충격적입니다. 혀는 길들일 수 없는 악이며 죽이는 독이 가득하다! 이것이 우리 모두의 현실입니다.", "예화_적용": "독사의 독은 한 방울로 사람을 죽일 수 있습니다. 말의 독도 한 마디로 사람을 죽일 수 있습니다."},
    {"대지": "1대지: 길들일 수 없는 악 (인간의 한계)", "내용": "동물은 길들일 수 있지만 혀는 길들일 수 없다. 인간의 의지력과 노력만으로는 혀를 완전히 제어할 수 없다.", "예화_적용": "금연, 다이어트도 어려운데, 말의 습관을 바꾸는 것은 더 어렵습니다."},
    {"대지": "2대지: 쉬지 않는 악 (끊임없는 위험)", "내용": "'아카타스타톤(쉬지 않는)'은 혀가 끊임없이 악을 행할 잠재력을 가지고 있음을 뜻한다. 한순간의 방심이 큰 화를 부른다.", "예화_적용": "활화산처럼 혀는 언제든 폭발할 수 있는 위험을 안고 있습니다."},
    {"대지": "3대지: 은혜만이 답이다 (성령의 역사)", "내용": "인간의 힘으로 불가능하지만 하나님의 은혜로 가능하다. 성령의 열매인 절제(갈 5:23)가 혀를 다스리는 유일한 길이다.", "예화_적용": "빌립보서 4:13 '내게 능력 주시는 자 안에서 내가 모든 것을 할 수 있느니라.' 혀의 절제도 포함됩니다."},
    {"대지": "결론", "내용": "우리의 혀에 독이 가득합니다. 인간의 노력만으로는 부족합니다. 성령의 능력을 구합시다. 독이 가득한 혀가 은혜로 치유의 혀, 격려의 혀, 찬양의 혀로 변화되기를 기도합시다.", "예화_적용": "'주님, 제 혀의 독을 빼시고 양약으로 채워주소서'라고 기도하십시오."}
