    {"항목": "정욕의 군사적 비유", "내용": "야고보는 정욕을 군사적 비유(전쟁, 싸움, 전투)로 묘사하는데, 이는 바울이 '육체의 소욕은 성령을 거스르고'(갈 5:17)라고 한 것과 베드로가 '영혼을 거스려 싸우는 육체의 정욕'(벧전 2:11)을 경고한 것과 같은 맥락이다.", "목회적활용": "내면의 욕망이 우리 안에서 전쟁하고 있다는 인식이 중요합니다. 외부의 적보다 내부의 적(정욕)이 더 위험함을 깨달아야 합니다."}
