    {"대지": "서론", "내용": "세 글자가 당신의 인생을 바꿀 수 있습니다: '주의 뜻이면.' 이 세 글자를 계획 앞에 두면, 교만이 겸손으로, 불안이 신뢰로, 자력이 의존으로 변합니다.", "예화_적용": "바울은 편지에서 자주 '주께서 허락하시면'이라고 썼습니다(고전 4:19). 위대한 사도도 이 전제 없이 계획하지 않았습니다."},
    {"대지": "1대지: 살기도 하고 — 생명이 주의 뜻 (존재)", "내용": "살아 있는 것 자체가 하나님의 뜻이고 은혜이다. 내일 아침 눈을 뜨는 것도 당연한 것이 아니라 은혜이다.", "예화_적용": "매일 아침 눈을 뜰 때 '주님, 오늘도 살게 하셨으니 감사합니다'라고 고백하십시오."},
    {"대지": "2대지: 이것이나 저것을 하리라 — 활동이 주의 뜻 (행위)", "내용": "무엇을 하든 하나님의 뜻 안에서 해야 한다. 사업도, 결혼도, 이사도 '주의 뜻이면'이라는 전제 아래 결정해야 한다.", "예화_적용": "중요한 결정을 할 때 '이것이 주의 뜻인가?'를 먼저 물으십시오."},
    {"대지": "3대지: 말하기를 — 고백이 습관이 되다 (실천)", "내용": "'주의 뜻이면'은 형식적 구호가 아니라 삶의 태도가 되어야 한다. 마음에서 우러나오는 진실한 고백이어야 한다.", "예화_적용": "습관이 성품이 됩니다. '주의 뜻이면'을 반복하다 보면 진심으로 하나님의 뜻을 구하는 삶이 됩니다."},
    {"대지": "결론", "내용": "오늘부터 모든 계획에 '주의 뜻이면'을 붙이십시오. 이 세 글자가 교만을 겸손으로, 불안을 신뢰로 바꿀 것입니다.", "예화_적용": "'주님, 주의 뜻이면 내일도 살게 하시고, 주의 뜻이면 이 일을 하게 하소서.'"}
