    {"대지": "서론", "내용": "모든 음식에는 유통기한이 있습니다. 아무리 좋은 음식도 유통기한이 지나면 버려야 합니다. 야고보는 세상 재물에도 유통기한이 있다고 말합니다: '너희 재물은 썩었고 너희 옷은 좀먹었다.'", "예화_적용": "고대 이집트 파라오들은 무덤에 금과 보석을 가득 채웠지만, 수천 년 후 도굴꾼들에 의해 빈 무덤만 남았습니다."},
    {"대지": "1대지: 썩는 재물 — 곡물의 부패 (물질의 한계)", "내용": "곡물은 저장하면 썩는다. 아무리 많이 쌓아도 부패를 막을 수 없다. 물질은 본질적으로 일시적이다.", "예화_적용": "이스라엘이 만나를 욕심내어 많이 모았을 때 벌레가 나고 냄새가 났습니다(출 16:20)."},
    {"대지": "2대지: 좀먹는 옷 — 겉치레의 허무 (외형의 한계)", "내용": "옷은 좀에 먹힌다. 외적 화려함은 시간 앞에 무력하다. 겉모습의 아름다움도 영원하지 않다.", "예화_적용": "박물관의 고대 의복은 보존 처리를 해도 원래의 광채를 잃었습니다. 시간은 모든 겉치레를 빼앗아 갑니다."},
    {"대지": "3대지: 영원한 보물 — 하늘에 쌓는 것 (대안)", "내용": "예수님은 '하늘에 보물을 쌓아두라'(마 6:20)고 하셨다. 좀도 녹도 해하지 못하고 도적이 훔치지 못하는 보물이 있다.", "예화_적용": "사랑, 섬김, 나눔, 전도의 열매는 영원히 남는 보물입니다."},
    {"대지": "결론", "내용": "유통기한 없는 보물을 쌓고 계십니까? 썩는 것에 투자하지 말고, 영원한 것에 투자하십시오.", "예화_적용": "'주님, 썩는 재물이 아닌 영원한 보물을 쌓는 삶을 살게 하소서.'"}
