  "표4_예표론": [
    {"구분": "맹세와 언약의 완성", "내용": "구약에서 하나님은 아브라함에게 자기를 두고 맹세하셨다(히 6:13). 이는 하나님 외에 더 큰 것이 없기 때문이다. 야고보가 인간의 맹세를 금한 것은, 인간은 하나님처럼 자기 맹세를 보증할 능력이 없기 때문이다.", "그리스도연결": "예수 그리스도는 '내가 곧 진리'(요 14:6)라고 선언하셨다. 그분은 맹세가 필요 없는 분이시며, 그분의 모든 말씀이 곧 진리이다. 그리스도인은 이 진리의 주님 안에서 맹세 없이도 진실한 말을 하는 자가 되어야 한다."}
  ],
  "표5_매튜헨리": [
    {"영어원문": "But above all things, my brethren, swear not, neither by heaven, neither by the earth, neither by any other oath: but let your yea be yea; and your nay, nay; lest ye fall into condemnation. The meaning here is not that all oaths are sinful, but that men should not be accustomed to swear in their common conversation.", "한국어번역": "내 형제들아 무엇보다도 맹세하지 말지니 하늘로나 땅으로나 아무 다른 것으로도 맹세하지 말라. 다만 너희 예는 예요, 아니오는 아니오라 하여 정죄를 받지 않도록 하라. 여기서의 의미는 모든 맹세가 죄라는 것이 아니라, 사람들이 일상 대화에서 맹세하는 습관을 들이지 말아야 한다는 것이다.", "핵심통찰": "일상적 맹세는 말의 인플레이션입니다. 말에 신뢰가 없으니 맹세로 보충하려 하는 것입니다. 그리스도인의 말은 맹세 없이도 신뢰받아야 합니다."}
  ],
