    {"새찬송가": "542", "통일찬송가": "476", "제목": "주의 친절한 팔에 안기세", "선정이유": "고난 중에 주님 품에 안기어 기도하는 찬양"},
    {"새찬송가": "22", "통일찬송가": "22", "제목": "만복의 근원 하나님", "선정이유": "기쁨의 순간에 모든 복의 근원이신 하나님을 찬양"},
    {"새찬송가": "453", "통일찬송가": "370", "제목": "나의 갈 길 다 가도록", "선정이유": "모든 상황에서 기도와 찬양으로 걸어가는 순례자의 찬양"}
