  "표8_상담적용": [
    {"상황": "고난 중에 기도가 되지 않는다고 고백하는 분", "성경원리": "야고보는 고난 중에 '기도하라'고 명령한다. 그러나 기도가 되지 않을 때도 있다. 로마서 8:26은 '우리가 마땅히 빌 바를 알지 못하나 오직 성령이 말할 수 없는 탄식으로 우리를 위하여 친히 간구하시느니라'고 한다. 기도가 되지 않을 때 성령이 대신 기도해 주신다.", "실제적용": "기도가 되지 않는 것에 대한 죄책감을 풀어주라. 한숨도 기도이고, 눈물도 기도이다. 형식적 기도가 아니라 하나님 앞에 있는 것 자체가 기도임을 알려주라. 함께 침묵의 기도를 나누는 것도 좋다"}
  ],
